@namespace sv_c5a1180a262243b88e08ab71ab0fe49d.Components.Pages.Board

<div class="task-card">
    <h4 class="task-title">@Task.Title</h4>
    <p class="task-assignee">@Task.Assignee</p>
    <span class="priority-badge priority-@Task.Priority.ToLowerInvariant()">@Task.Priority</span>
    <span class="task-due-date">@Task.DueDate.ToString("MMM dd")</span>
    <div class="task-actions">
        @if (ShowMoveLeft)
        {
            <button class="btn-move-left" @onclick="() => OnMoveLeft.InvokeAsync(Task)">Move Left</button>
        }
        @if (ShowMoveRight)
        {
            <button class="btn-move-right" @onclick="() => OnMoveRight.InvokeAsync(Task)">Move Right</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public TaskItem Task { get; set; } = default!;

    [Parameter]
    public bool ShowMoveLeft { get; set; }

    [Parameter]
    public bool ShowMoveRight { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveRight { get; set; }
}

@namespace sv_c5a1180a262243b88e08ab71ab0fe49d.Components.Pages.Board

<div class="add-task-form">
    <input type="text" placeholder="Title" @bind="title" />
    <input type="text" placeholder="Assignee" @bind="assignee" />
    <select @bind="priority">
        <option value="High">High</option>
        <option value="Medium">Medium</option>
        <option value="Low">Low</option>
    </select>
    <input type="date" @bind="dueDate" />
    <div class="form-actions">
        <button class="btn-save" @onclick="Save">Save</button>
        <button class="btn-cancel" @onclick="Cancel">Cancel</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public string Status { get; set; } = default!;

    [Parameter]
    public EventCallback<NewTaskModel> OnSave { get; set; }

    [Parameter]
    public EventCallback OnCancel { get; set; }

    private string title = string.Empty;
    private string assignee = string.Empty;
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);

    private async Task Save()
    {
        if (string.IsNullOrWhiteSpace(title)) return;

        await OnSave.InvokeAsync(new NewTaskModel(title, assignee, priority, dueDate, Status));
        ResetForm();
    }

    private async Task Cancel()
    {
        ResetForm();
        await OnCancel.InvokeAsync();
    }

    private void ResetForm()
    {
        title = string.Empty;
        assignee = string.Empty;
        priority = "Medium";
        dueDate = DateTime.Today.AddDays(7);
    }

    public record NewTaskModel(string Title, string Assignee, string Priority, DateTime DueDate, string Status);
}

@namespace sv_c5a1180a262243b88e08ab71ab0fe49d.Components.Pages.Board

<div class="board-column">
    <div class="column-header">
        <h3>@ColumnName (@Tasks.Count)</h3>
    </div>
    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowMoveLeft"
                      ShowMoveRight="ShowMoveRight"
                      OnMoveLeft="OnMoveLeft"
                      OnMoveRight="OnMoveRight" />
        }
    </div>
    <div class="column-footer">
        @if (showForm)
        {
            <AddTaskForm Status="@Status" OnSave="OnTaskCreated" OnCancel="HideForm" />
        }
        else
        {
            <button class="btn-add-task" @onclick="ShowForm">Add Task</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public string ColumnName { get; set; } = default!;

    [Parameter, EditorRequired]
    public string Status { get; set; } = default!;

    [Parameter]
    public List<TaskItem> Tasks { get; set; } = new();

    [Parameter]
    public bool ShowMoveLeft { get; set; }

    [Parameter]
    public bool ShowMoveRight { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveRight { get; set; }

    [Parameter]
    public EventCallback<AddTaskForm.NewTaskModel> OnTaskCreated { get; set; }

    private bool showForm;

    private void ShowForm() => showForm = true;

    private void HideForm() => showForm = false;
}

@namespace sv_c5a1180a262243b88e08ab71ab0fe49d.Components.Pages.Board

<div class="board-stats">
    <span class="stat-item">Total: @Total</span>
    <span class="stat-item">To Do: @ToDo</span>
    <span class="stat-item">In Progress: @InProgress</span>
    <span class="stat-item">Done: @Done</span>
    <span class="stat-item stat-overdue">Overdue: @Overdue</span>
</div>

@code {
    [Parameter]
    public int Total { get; set; }

    [Parameter]
    public int ToDo { get; set; }

    [Parameter]
    public int InProgress { get; set; }

    [Parameter]
    public int Done { get; set; }

    [Parameter]
    public int Overdue { get; set; }
}

@namespace sv_c5a1180a262243b88e08ab71ab0fe49d.Components.Pages.Board

<div class="board-search">
    <input type="text" placeholder="Search tasks by title..." value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter]
    public string SearchText { get; set; } = string.Empty;

    [Parameter]
    public EventCallback<string> OnSearchChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        await OnSearchChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty);
    }
}

