+                     Tasks="filteredTodo"
+                     ShowMoveLeft="false"
+                     ShowMoveRight="true"
+                     OnMoveRight="MoveRight"
+                     OnTaskCreated="HandleTaskCreated" />
+
+        <BoardColumn ColumnName="In Progress"
+                     Status="In Progress"
+                     Tasks="filteredInProgress"
+                     ShowMoveLeft="true"
+                     ShowMoveRight="true"
+                     OnMoveLeft="MoveLeft"
+                     OnMoveRight="MoveRight"
+                     OnTaskCreated="HandleTaskCreated" />
+
+        <BoardColumn ColumnName="Done"
+                     Status="Done"
+                     Tasks="filteredDone"
+                     ShowMoveLeft="true"
+                     ShowMoveRight="false"
+                     OnMoveLeft="MoveLeft"
+                     OnTaskCreated="HandleTaskCreated" />
+    </div>
+}
+
+@code {
+    private List<TaskItem> allTasks = new();
+    private string searchText = string.Empty;
+    private bool isLoading = true;
+    private string? errorMessage;
+
+    private static readonly string[] Statuses = { "To Do", "In Progress", "Done" };
+
+    private List<TaskItem> todoTasks => allTasks.Where(t => t.Status == "To Do").ToList();
+    private List<TaskItem> inProgressTasks => allTasks.Where(t => t.Status == "In Progress").ToList();
+    private List<TaskItem> doneTasks => allTasks.Where(t => t.Status == "Done").ToList();
+    private int overdueTasks => allTasks.Count(t => t.DueDate < DateTime.Today);
+
+    private List<TaskItem> filteredTodo => Filter(todoTasks);
+    private List<TaskItem> filteredInProgress => Filter(inProgressTasks);
+    private List<TaskItem> filteredDone => Filter(doneTasks);
+
+    private List<TaskItem> Filter(List<TaskItem> tasks)
+    {
+        if (string.IsNullOrWhiteSpace(searchText)) return tasks;
+        return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
+    }
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private void HandleSearchChanged(string value)
+    {
+        searchText = value;
+    }
+
+    private async Task MoveLeft(TaskItem task)
+    {
+        var currentIndex = Array.IndexOf(Statuses, task.Status);
+        if (currentIndex <= 0) return;
+
+        var newStatus = Statuses[currentIndex - 1];
+        await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
+        allTasks = allTasks.Select(t => t.Id == task.Id ? t with { Status = newStatus } : t).ToList();
+    }
+
+    private async Task MoveRight(TaskItem task)
+    {
+        var currentIndex = Array.IndexOf(Statuses, task.Status);
+        if (currentIndex >= Statuses.Length - 1) return;
+
+        var newStatus = Statuses[currentIndex + 1];
+        await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
+        allTasks = allTasks.Select(t => t.Id == task.Id ? t with { Status = newStatus } : t).ToList();
+    }
+
+    private async Task HandleTaskCreated(AddTaskForm.NewTaskModel model)
+    {
+        var newTask = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
+        allTasks.Add(newTask with { Status = model.Status });
+    }
+}
